urlset:

  {{ base_url }}/
  daily
  1.0


  {{ base_url }}/posts
  daily
  0.8


  {{ base_url }}/contact
  monthly
  0.5

{% for post in posts %}

  {{ base_url }}/posts/{{ post.slug }}
  {{ post.updated_at.strftime('%Y-%m-%d') }}
  weekly
  0.7

{% endfor %}
{% for page in pages %}

  {{ base_url }}/{{ page.slug }}
  {{ page.updated_at.strftime('%Y-%m-%d') }}
  weekly
  0.6

{% endfor %}
